package cn.zhuatech.clm.controller; import cn.zhuatech.clm.common.ApiResponse; import cn.zhuatech.clm.dto.ClmDto.*; import cn.zhuatech.clm.service.ClmService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('CONTRACT_MANAGER','QUALITY','ADMIN')") public class ContractAdminController {private final ClmService service;public ContractAdminController(ClmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<ContractReviewView>> orders(){return ApiResponse.ok(service.contractReviews());}}
